let i=1;const s=new Map;function c(){return new Date().toISOString()}function o(){if(s.size)return;const e=["Cachorro","Gato","Coelho","Pássaro","Hamster"];for(const n of e){const t={id:String(i++),nome:n,created_at:c()};s.set(t.id,t)}}async function a(){return o(),{}}function u(e){o();const n=Array.from(s.values()),t=(e??"").trim().toLowerCase();return t?n.filter(r=>r.nome.toLowerCase().includes(t)):n}async function d(e){return o(),s.get(e)??null}async function l(e){o();const n={id:String(i++),nome:e.nome.trim(),created_at:c()};return s.set(n.id,n),n}async function f(e,n){o();const t=s.get(e);if(!t)return null;const r={...t,nome:n.nome.trim()};return s.set(e,r),r}export{u as a,l as c,d as g,a as l,f as u};
